/// Arsenal's patch: what its modules change in Horizon's drawing, chat, sounds and input. Its mod sets these each
/// tick; each is read where Horizon does that thing. Zero or empty leaves Horizon's own.
pub mod arsenal {
    use std::sync::atomic::{AtomicBool, AtomicU32, AtomicU8, AtomicUsize, Ordering::Relaxed};
    use std::sync::{Mutex, RwLock};

    /// Hotbar Style: the hotbar's background (0xAARRGGBB, 0 = Horizon's) and the selected slot's accent.
    pub static HOTBAR: AtomicU32 = AtomicU32::new(0);
    pub static HOTBAR_ACCENT: AtomicU32 = AtomicU32::new(0);
    /// Smooth Hotbar: the selection box glides; where it is now (pixels from the first slot, f32 bits).
    pub static HOTBAR_GLIDE: AtomicBool = AtomicBool::new(false);
    static GLIDE_X: Mutex<f32> = Mutex::new(-1.0);
    /// Inventory Style: a frame round inventories in this colour (0xAARRGGBB, 0 = none).
    pub static INV_FRAME: AtomicU32 = AtomicU32::new(0);
    /// Smooth Inventory: the item on the cursor glides after it.
    pub static INV_GLIDE: AtomicBool = AtomicBool::new(false);
    static CARRIED: Mutex<Option<(f32, f32)>> = Mutex::new(None);
    /// Swing Animation: the swing's length in percent of vanilla's.
    pub static SWING: AtomicU32 = AtomicU32::new(100);
    /// 1.8 Animations: held items lower (hundredths of a block) and the sword block-hit pose.
    pub static LOWER: AtomicU32 = AtomicU32::new(0);
    pub static BLOCKHIT: AtomicBool = AtomicBool::new(false);
    /// Hand Tint & Glow: the hand's tint (0xRRGGBB, 0 = none) and full brightness.
    pub static HAND_TINT: AtomicU32 = AtomicU32::new(0);
    pub static HAND_GLOW: AtomicBool = AtomicBool::new(false);
    /// Smaller Crystals: size in percent and whether they spin.
    pub static CRYSTAL_SIZE: AtomicU32 = AtomicU32::new(100);
    pub static CRYSTAL_STILL: AtomicBool = AtomicBool::new(false);
    /// Big Items: dropped items drawn this many times bigger (item id, scale).
    pub static BIG_ITEMS: RwLock<Vec<(String, f32)>> = RwLock::new(Vec::new());
    /// Armor Color: worn armour tinted (0xRRGGBB, 0 = none).
    pub static ARMOR_TINT: AtomicU32 = AtomicU32::new(0);
    /// Nametag Style: size in percent and background (0xAARRGGBB; vanilla's is 0x3F000000).
    pub static TAG_SIZE: AtomicU32 = AtomicU32::new(100);
    pub static TAG_BG: AtomicU32 = AtomicU32::new(0x3F00_0000);
    /// Free Look: the camera's own rotation while held, and the view it came from (0 first person, 1 back, 2 front).
    static FREELOOK: Mutex<Option<(f32, f32)>> = Mutex::new(None);
    pub static FREELOOK_FROM: AtomicU8 = AtomicU8::new(0);
    /// Block Break and Place Animation: blocks you broke (0) or placed (1) since the mod last asked.
    pub static BLOCKS: Mutex<Vec<([i32; 3], u8)>> = Mutex::new(Vec::new());
    /// Tab List Ping: pings as numbers; set when it changes so the cached layout is made again.
    pub static TAB_PING: AtomicBool = AtomicBool::new(false);
    pub static TAB_DIRTY: AtomicBool = AtomicBool::new(false);
    /// Name Hider: your name and what's shown instead.
    pub static NAME_HIDE: RwLock<Option<(String, String)>> = RwLock::new(None);
    /// Chat Mentions: lines holding this (lower case) are highlighted.
    pub static MENTION: RwLock<String> = RwLock::new(String::new());
    /// Chat Tweaks: how many lines the chat keeps.
    pub static CHAT_KEEP: AtomicUsize = AtomicUsize::new(100);
    /// Sound Tweaks: sounds whose id holds the text play at this volume.
    pub static VOLUMES: RwLock<Vec<(String, f32)>> = RwLock::new(Vec::new());
    /// Obsidian Click Guard and Crystal Helper.
    pub static OBSIDIAN_GUARD: AtomicBool = AtomicBool::new(false);
    pub static CRYSTAL_HELP: AtomicBool = AtomicBool::new(false);
    /// Screenshot to Clipboard: the last screenshot saved.
    pub static SHOT: Mutex<Option<std::path::PathBuf>> = Mutex::new(None);
    /// Inventory Cursor Speed: percent of the mouse's speed (100 off), whether Arsenal's cursor is the one shown, and
    /// where the real one was.
    pub static CURSOR_SPEED: AtomicU32 = AtomicU32::new(100);
    pub static CURSOR_ON: AtomicBool = AtomicBool::new(false);
    static RAW: Mutex<Option<(f32, f32)>> = Mutex::new(None);

    /// Arsenal's cursor after the real one moved to `raw`: it moves by the real one's step times the speed.
    pub fn virtual_cursor(previous: (f32, f32), raw: (f32, f32), bounds: (f32, f32)) -> (f32, f32) {
        let k = CURSOR_SPEED.load(Relaxed) as f32 / 100.0;
        let mut r = RAW.lock().unwrap_or_else(|e| e.into_inner());
        let last = r.unwrap_or(raw);
        *r = Some(raw);
        let from = if CURSOR_ON.swap(true, Relaxed) { previous } else { raw };
        ((from.0 + (raw.0 - last.0) * k).clamp(0.0, bounds.0), (from.1 + (raw.1 - last.1) * k).clamp(0.0, bounds.1))
    }
    /// Arsenal Cosmetics: each player's Wardrobe blade (item model) and Arsenal cape (a picture on disk).
    static BLADES: RwLock<Vec<(u128, String)>> = RwLock::new(Vec::new());
    static CAPES: RwLock<Vec<(u128, std::path::PathBuf)>> = RwLock::new(Vec::new());
    pub static PACK_ON: AtomicBool = AtomicBool::new(false);
    pub static PACK_TRIED: AtomicBool = AtomicBool::new(false);
    pub fn blade_for(uuid: u128) -> Option<String> {
        if !PACK_ON.load(Relaxed) {
            return None;
        }
        BLADES.read().ok()?.iter().find(|b| b.0 == uuid).map(|b| b.1.clone())
    }
    pub fn capes() -> Vec<(u128, std::path::PathBuf)> {
        CAPES.read().map(|c| c.clone()).unwrap_or_default()
    }
    /// True when they changed.
    pub fn set_blades(v: Vec<(u128, String)>) -> bool {
        let mut b = BLADES.write().unwrap_or_else(|e| e.into_inner());
        let changed = *b != v;
        *b = v;
        changed
    }
    pub fn set_capes(v: Vec<(u128, std::path::PathBuf)>) -> bool {
        let mut c = CAPES.write().unwrap_or_else(|e| e.into_inner());
        let changed = *c != v;
        *c = v;
        changed
    }
    pub fn reset_cursor() {
        *RAW.lock().unwrap_or_else(|e| e.into_inner()) = None;
    }

    static GLIDE_AT: Mutex<Option<std::time::Instant>> = Mutex::new(None);
    pub fn hotbar_x(selected: i32) -> i32 {
        let target = selected as f32 * 20.0;
        if !HOTBAR_GLIDE.load(Relaxed) {
            return selected * 20;
        }
        let mut x = GLIDE_X.lock().unwrap_or_else(|e| e.into_inner());
        let mut at = GLIDE_AT.lock().unwrap_or_else(|e| e.into_inner());
        let now = std::time::Instant::now();
        let dt = at.map_or(1.0, |a| now.duration_since(a).as_secs_f32().min(0.1));
        *at = Some(now);
        if *x < 0.0 || (target - *x).abs() > 180.0 {
            *x = target;
        }
        *x += (target - *x) * (1.0 - (-dt * 18.0).exp());
        if (target - *x).abs() < 0.5 {
            *x = target;
        }
        x.round() as i32
    }
    static CARRIED_AT: Mutex<Option<std::time::Instant>> = Mutex::new(None);
    pub fn carried(cursor: (f32, f32)) -> (f32, f32) {
        let mut at = CARRIED.lock().unwrap_or_else(|e| e.into_inner());
        let mut when = CARRIED_AT.lock().unwrap_or_else(|e| e.into_inner());
        let now = std::time::Instant::now();
        let gap = when.map_or(1.0, |w| now.duration_since(w).as_secs_f32());
        *when = Some(now);
        // Off, or nothing carried a moment ago (a new pick-up): it starts at the cursor.
        if !INV_GLIDE.load(Relaxed) || gap > 0.15 {
            *at = Some(cursor);
            return cursor;
        }
        let (x, y) = at.unwrap_or(cursor);
        let k = 1.0 - (-gap * 22.0).exp();
        let next = (x + (cursor.0 - x) * k, y + (cursor.1 - y) * k);
        *at = Some(next);
        next
    }
    pub fn swing(duration: i32) -> i32 {
        ((duration as f32) * SWING.load(Relaxed) as f32 / 100.0).round().max(1.0) as i32
    }
    pub fn lower() -> f32 {
        LOWER.load(Relaxed) as f32 / 100.0
    }
    /// Multiplies an ABGR (RGBA8) colour by the 0xRRGGBB tint.
    pub fn tint_abgr(color: u32, tint: u32) -> u32 {
        let [r, g, b] = [(tint >> 16) & 255, (tint >> 8) & 255, tint & 255];
        let ch = |shift: u32, by: u32| (((color >> shift) & 255) * by / 255) << shift;
        (color & 0xFF00_0000) | ch(0, r) | ch(8, g) | ch(16, b)
    }
    pub fn crystal_size() -> f32 {
        CRYSTAL_SIZE.load(Relaxed) as f32 / 100.0
    }
    pub fn crystal_age(age: f32) -> f32 {
        if CRYSTAL_STILL.load(Relaxed) { 0.0 } else { age }
    }
    pub fn item_scale(id: &str) -> f32 {
        BIG_ITEMS.read().ok().and_then(|l| l.iter().find(|(i, _)| i == id || i == "*").map(|e| e.1)).unwrap_or(1.0)
    }
    pub fn armor(color: u32) -> u32 {
        match ARMOR_TINT.load(Relaxed) {
            0 => color,
            t => tint_abgr(color, t),
        }
    }
    pub fn tag_size() -> f32 {
        TAG_SIZE.load(Relaxed) as f32 / 100.0
    }
    pub fn freelook() -> Option<(f32, f32)> {
        *FREELOOK.lock().unwrap_or_else(|e| e.into_inner())
    }
    pub fn set_freelook(at: Option<(f32, f32)>) {
        *FREELOOK.lock().unwrap_or_else(|e| e.into_inner()) = at;
    }
    /// The mouse turns the free camera instead of the player (`Entity.turn`'s 0.15).
    pub fn freelook_turn(xo: f64, yo: f64) -> bool {
        let mut f = FREELOOK.lock().unwrap_or_else(|e| e.into_inner());
        let Some((yaw, pitch)) = f.as_mut() else { return false };
        *yaw += (xo * 0.15) as f32;
        *pitch = (*pitch + (yo * 0.15) as f32).clamp(-90.0, 90.0);
        true
    }
    /// Quick Menu: while V is held the mouse moves a pointer on its wheel (how far from the middle) instead of turning.
    static QUICK: Mutex<Option<(f32, f32)>> = Mutex::new(None);
    pub fn set_quick(open: bool) {
        let mut q = QUICK.lock().unwrap_or_else(|e| e.into_inner());
        match (open, q.is_some()) {
            (true, false) => *q = Some((0.0, 0.0)),
            (false, _) => *q = None,
            _ => {}
        }
    }
    pub fn quick_aim() -> Option<(f32, f32)> {
        *QUICK.lock().unwrap_or_else(|e| e.into_inner())
    }
    pub fn quick_turn(xo: f64, yo: f64) -> bool {
        let mut q = QUICK.lock().unwrap_or_else(|e| e.into_inner());
        let Some((x, y)) = q.as_mut() else { return false };
        *x += (xo * 0.15) as f32;
        *y += (yo * 0.15) as f32;
        let len = (*x * *x + *y * *y).sqrt();
        if len > 40.0 {
            *x *= 40.0 / len;
            *y *= 40.0 / len;
        }
        true
    }
    pub fn block(pos: [i32; 3], kind: u8) {
        if let Ok(mut b) = BLOCKS.lock() {
            if b.len() < 64 {
                b.push((pos, kind));
            }
        }
    }
    pub fn tab_extra() -> i32 {
        if TAB_PING.load(Relaxed) { 14 } else { 0 }
    }
    pub fn ping_colour(ms: i32) -> u32 {
        match ms {
            i32::MIN..0 => 0xFFAAAAAA,
            0..80 => 0xFF55FF55,
            80..150 => 0xFFFFFF55,
            150..300 => 0xFFFFAA00,
            _ => 0xFFFF5555,
        }
    }
    pub fn hide_name(text: &crate::text::Text) -> Option<crate::text::Text> {
        let hide = NAME_HIDE.read().ok()?;
        let (name, shown) = hide.as_ref()?;
        if name.is_empty() || !text.spans.iter().any(|s| s.text.contains(name.as_str())) {
            return None;
        }
        let mut t = text.clone();
        for s in &mut t.spans {
            s.text = s.text.replace(name.as_str(), shown);
        }
        Some(t)
    }
    pub fn mentions(line: &str) -> bool {
        MENTION.read().is_ok_and(|m| !m.is_empty() && line.to_lowercase().contains(m.as_str()))
    }
    pub fn chat_keep() -> usize {
        CHAT_KEEP.load(Relaxed).clamp(100, 1000)
    }
    pub fn volume(id: &str) -> f32 {
        VOLUMES.read().ok().and_then(|v| v.iter().find(|(k, _)| id.contains(k.as_str())).map(|e| e.1)).unwrap_or(1.0)
    }
}

