/// The sidebar as plain lines, title first, as drawn (Arsenal's patch: Hypixel SkyBlock reads it).
pub(super) fn arsenal_sidebar(&self) -> Vec<String> {
    let board = &self.score.board;
    let Some(objective) = self.sidebar_objective() else {
        return Vec::new();
    };
    let mut entries: Vec<_> = board.list_scores(&objective.name).into_iter().filter(|e| !e.is_hidden()).collect();
    hud_overlays::java_sort(&mut entries, |a, b| b.value.cmp(&a.value).then_with(|| hud_overlays::compare_ignore_case(&a.owner, &b.owner)));
    entries.truncate(15);
    let mut out = vec![objective.display_text().resolve_legacy().plain()];
    out.extend(entries.iter().map(|e| match board.players_team(&e.owner) {
        Some(team) => team.formatted_name(e.owner_name()),
        None => e.owner_name(),
    }.resolve_legacy().plain()));
    out
}
/// The tab list as plain lines: its header, each player's name as shown, its footer (Arsenal's patch).
pub(super) fn arsenal_tab_lines(&self) -> Vec<String> {
    let players = self.remote.as_ref().map(|r| r.arsenal_tab_players()).unwrap_or_default();
    let board = &self.score.board;
    let mut out: Vec<String> = self.tab_list.header.iter().map(|t| t.resolve_legacy().plain()).collect();
    out.extend(horizon_client::tab_list::sorted_players(&players, board).into_iter().map(|p| horizon_client::tab_list::name_for_display(p, board).resolve_legacy().plain()));
    out.extend(self.tab_list.footer.iter().map(|t| t.resolve_legacy().plain()));
    out
}

