/// Inventory Cursor Speed (Arsenal's patch): in inventories the cursor moves at its own speed and Arsenal draws it;
/// the real one is hidden there, never moved.
pub(super) fn arsenal_cursor(&mut self, previous: (f32, f32)) {
    use horizon_client::camera::arsenal as a;
    use std::sync::atomic::Ordering::Relaxed;
    let on = matches!(self.screen, super::Screen::Inventory | super::Screen::Creative) && a::CURSOR_SPEED.load(Relaxed) != 100;
    let bounds = self.renderer.as_ref().map(|r| {
        let b = HudBatch::new([r.config.width, r.config.height]);
        (b.width, b.height)
    });
    match (on, bounds) {
        (true, Some(bounds)) => {
            self.cursor = a::virtual_cursor(previous, self.cursor, bounds);
            if let Some(w) = &self.window {
                w.set_cursor_visible(false);
            }
        }
        _ => {
            a::reset_cursor();
            if a::CURSOR_ON.swap(false, Relaxed) && !self.captured {
                if let Some(w) = &self.window {
                    w.set_cursor_visible(true);
                }
            }
        }
    }
}
/// Free Look's camera (held: third person on its own rotation), Chat Tweaks, Click to Copy Chat and Auto Reconnect
/// (Horizon's own PvP extras; None leaves them), Arsenal's patch.
pub(super) fn arsenal_more(&mut self, freelook: bool, chat: [Option<bool>; 3], reconnect: Option<bool>) {
    use super::perspective::CameraType as C;
    use horizon_client::camera::arsenal as a;
    use std::sync::atomic::Ordering::Relaxed;
    let on = freelook && self.native_playing();
    if on && a::freelook().is_none() {
        a::FREELOOK_FROM.store(match self.camera_type { C::FirstPerson => 0, C::ThirdPersonBack => 1, C::ThirdPersonFront => 2 }, Relaxed);
        self.camera_type = C::ThirdPersonBack;
        a::set_freelook(Some((self.yaw, self.pitch)));
    } else if !on && a::freelook().is_some() {
        self.camera_type = match a::FREELOOK_FROM.load(Relaxed) { 1 => C::ThirdPersonBack, 2 => C::ThirdPersonFront, _ => C::FirstPerson };
        a::set_freelook(None);
    }
    static KEPT: std::sync::Mutex<[Option<bool>; 4]> = std::sync::Mutex::new([None; 4]);
    let mut kept = KEPT.lock().unwrap_or_else(|e| e.into_inner());
    let c = &mut self.settings.extras.pvp.chat;
    let mut swap = |slot: usize, now: &mut bool, change: Option<bool>| match change {
        Some(true) => {
            kept[slot] = Some(*now);
            *now = true;
        }
        Some(false) => *now = kept[slot].take().unwrap_or(false),
        None => {}
    };
    swap(0, &mut c.timestamps, chat[0]);
    swap(1, &mut c.compact, chat[1]);
    swap(2, &mut c.copy, chat[2]);
    swap(3, &mut self.settings.extras.auto_reconnect, reconnect);
}
