/// The server you're on (Arsenal's patch).
pub(super) fn arsenal_server(&self) -> Option<String> {
    self.remote.as_ref().map(|r| r.session.address.clone())
}
/// Wardrobe blades (Arsenal's patch): a sword held by the player with `uuid` as their blade's model.
pub(super) fn arsenal_blade(&self, stack: &ItemStack, uuid: Option<u128>) -> ItemStack {
    let mut out = stack.clone();
    if stack.item.ends_with("_sword") {
        if let Some(model) = uuid.and_then(horizon_client::camera::arsenal::blade_for) {
            out.data_mut().set_other("minecraft:item_model", Some(horizon_world::nbt::Tag::String(model.as_str().into())));
        }
    }
    out
}
pub(super) fn arsenal_own_blade(&self, stack: &ItemStack) -> ItemStack {
    self.arsenal_blade(stack, horizon_client::auth::current().map(|s| s.uuid))
}
/// Arsenal's cosmetics pack (blade models) on (Arsenal's patch).
pub(super) fn arsenal_enable_pack(&mut self) {
    use std::sync::atomic::Ordering::Relaxed;
    const PACK: &str = "file/arsenal.zip";
    let on = self.settings.resource_packs.iter().any(|p| p == PACK);
    horizon_client::camera::arsenal::PACK_ON.store(on, Relaxed);
    // Once a start: a pack that fails to load isn't asked for again and again.
    if !on && !horizon_client::camera::arsenal::PACK_TRIED.swap(true, Relaxed) {
        self.settings.resource_packs.push(PACK.into());
        self.settings.save(&Self::options_path());
        self.reload_packs();
    }
}
/// Each tick: out of inventories, Arsenal's cursor is put away (Arsenal's patch).
pub(super) fn arsenal_cursor_tick(&mut self) {
    use horizon_client::camera::arsenal as a;
    use std::sync::atomic::Ordering::Relaxed;
    if a::CURSOR_ON.load(Relaxed) && !matches!(self.screen, super::Screen::Inventory | super::Screen::Creative) {
        a::CURSOR_ON.store(false, Relaxed);
        a::reset_cursor();
        if !self.captured {
            if let Some(w) = &self.window {
                w.set_cursor_visible(true);
            }
        }
    }
}
/// Arsenal capes changed: the players' capes are chosen again (Arsenal's patch).
pub(super) fn arsenal_capes_changed(&mut self) {
    self.update_remote_skins();
}
