/// Text with its own opacity (0xAARRGGBB) and size, for Arsenal's menu (Arsenal's patch).
pub(super) fn arsenal_text(&self, batch: &mut HudBatch, text: &str, at: [f32; 2], argb: u32, shadow: bool, scale: f32) {
    let [a, r, g, b] = argb.to_be_bytes();
    if a < 4 {
        return;
    }
    let start = batch.vertices.len();
    batch.text_styled(&self.gui.atlas, &Text::literal(text), at[0], at[1], rgba(r, g, b, a), shadow);
    if scale != 1.0 {
        batch.scale_since(start, at[0], at[1], scale, scale);
    }
}
/// Arsenal's patch: a request body for the Arsenal API signed with your Mojang chat key, as the Java mod signs them
/// ({uuid, ts, sig, cert}). Only Arsenal's own messages: the key never signs anything else, and neither the key nor
/// your access token leaves Horizon. None for offline accounts or while the key isn't fetched yet.
pub(super) fn arsenal_signed(&self, prefix: &str, extra: &[String]) -> Option<String> {
    const ALLOWED: &[&str] = &["arsenal-hello-v1", "arsenal-config-load-v1", "arsenal-config-save-v1"];
    if !ALLOWED.contains(&prefix) {
        return None;
    }
    fn b64(data: &[u8]) -> String {
        const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        let mut out = String::with_capacity(data.len().div_ceil(3) * 4);
        for c in data.chunks(3) {
            let n = (u32::from(c[0]) << 16) | (u32::from(*c.get(1).unwrap_or(&0)) << 8) | u32::from(*c.get(2).unwrap_or(&0));
            out.push(T[(n >> 18) as usize & 63] as char);
            out.push(T[(n >> 12) as usize & 63] as char);
            out.push(if c.len() > 1 { T[(n >> 6) as usize & 63] as char } else { '=' });
            out.push(if c.len() > 2 { T[n as usize & 63] as char } else { '=' });
        }
        out
    }
    let session = horizon_client::auth::current()?;
    let keys = horizon_client::auth::chat_keys_for(session.uuid)?;
    let uuid = horizon_protocol::crypto::uuid_string(session.uuid);
    let ts = horizon_client::auth::now_millis();
    let mut message = format!("{prefix}:{uuid}:{ts}");
    for e in extra {
        message.push(':');
        message.push_str(e);
    }
    let sig = keys.private.sign(horizon_protocol::rsa::SignatureHash::Sha256, message.as_bytes()).ok()?;
    Some(serde_json::json!({
        "uuid": uuid,
        "ts": ts,
        "sig": b64(&sig),
        "cert": { "expiresAt": keys.public.expires_at, "key": b64(&keys.public.key), "keySig": b64(&keys.public.signature) },
    }).to_string())
}
